    # 排空时限 t ∈ [1, 10^9]，非 bool 整数。
    if (
        not isinstance(value, int)
        or isinstance(value, bool)
        or not 1 <= value <= 10 ** 9
    ):
        fail(EXIT_INPUT, "INPUT")
    return value


